        '황금 수액 잔치가 열렸습니다. 이 방의 몬스터가 모두 금빛 수액 슬라임이 되었습니다.': '黄金樹液の宴が開かれました。この部屋のモンスターがすべて金色の樹液スライムになりました。',
        '세계수가 하품을 했습니다. 이 방의 몬스터가 잠시 잠들었습니다.': '世界樹があくびをしました。この部屋のモンスターがしばらく眠りました。',
