        '♜ [{name}] 재도전 완료, 최초 격파 보상은 이미 획득했습니다.': '♜ [{name}] 再挑戦完了、初撃破報酬はすでに獲得済みです。',
        '{prefix} [{name}] 최초 격파{rewardText}': '{prefix} [{name}] 初撃破{rewardText}',
        '👑 [{name}] 획득!': '👑 [{name}] を獲得!',
        '선택한 보상이 잠겨 있어 이번 도전 보상을 장비로 지급합니다.': '選んだ報酬がロックされているため、今回の挑戦報酬は装備で支給します。',
        '경계 완료 보상: [{name}]': '境界完了報酬: [{name}]',
