        '경계 너머 {tier}단계 돌파, {sealText}, {summary}': '境界の彼方 {tier}段階を突破、{sealText}、{summary}',
        '🪓 나무꾼을 쓰러뜨렸습니다. 다음 경계가 열립니다.': '🪓 木こりを倒しました。次の境界が開きます。',
        '🌊 수심 {pendingBoundary}m의 심해 가디언을 처치했습니다! 더 깊은 곳으로 길이 열립니다. (암초 조각 +3)': '🌊 水深{pendingBoundary}mの深海ガーディアンを討伐しました! さらに深い場所への道が開きます。(岩礁の欠片 +3)',
        '🌌 혼돈계 {floor}층 돌파!': '🌌 混沌界{floor}層を突破!',
        '☁️ 창공의 탑 {floor}층 연습 완료.': '☁️ 蒼穹の塔{floor}層の練習完了。',
        '☁️ 창공의 탑 {floor}층 돌파! {rewardText}, 이번 루프 잔여 클리어 {skyTowerRemainingClears}/{skyTowerLoopClearLimit}': '☁️ 蒼穹の塔{floor}層を突破! {rewardText}、今回のループの残りクリア {skyTowerRemainingClears}/{skyTowerLoopClearLimit}',
        '⏳ 과거의 제단이 열렸습니다. (시간압 {pressure}) 시간의 균열에서 장비를 골라 같은 부위의 고유 1개/희귀 1개를 올리세요.': '⏳ 過去の祭壇が開きました。(時間圧 {pressure}) 時の亀裂で装備を選び、同じ部位のユニーク1個/レア1個を載せてください。',
        '👑 [{name}] 통과! 전직 포인트 2점 획득!': '👑 [{name}] 突破! 転職ポイント2点を獲得!',
        '🔁 [{name}] 재도전 완료 (전직 포인트 보상 없음)': '🔁 [{name}] 再挑戦完了 (転職ポイント報酬なし)',
        '❄️ 개화 미궁의 수호자를 아직 쓰러뜨리지 못했습니다. 전투를 다시 구성합니다.': '❄️ 開花の迷宮の守護者をまだ倒せていません。戦闘を組み直します。',
        '💠 키스톤 포인트 +1 (현재 {ascendKeystonePoints})': '💠 キーストーンポイント +1 (現在 {ascendKeystonePoints})',
