        '🗝️ [{name}] 토벌 완료!': '🗝️ [{name}] 討伐完了!',
        '🗡️ 완성작이 무릎 꿇었습니다. 버려진 날이 벼려진 날을 이겼습니다.': '🗡️ 完成作が膝をつきました。見捨てられた刃が鍛えられた刃に勝ちました。',
        '🗡️ 버려진 날 격파! 이번 루프에 남은 날: {remaining}개 (모두 꺾으면 「완성작」이 나타납니다)': '🗡️ 見捨てられた刃を撃破! 今回のループに残る刃: {remaining}本 (すべて折ると「完成作」が現れます)',
