        '🌌 잔향체가 흩어졌습니다. 다섯 별의 메아리가 마침내 잠잠해집니다.': '🌌 残響体が散りました。五つの星の木霊がついに静まります。',
        '🔁 입장권 1개 소모, [{name}] 자동 재도전 시작! (남은 열쇠 {value})': '🔁 入場券1枚を消費、[{name}] の自動再挑戦を開始! (残りの鍵 {value})',
        '🔁 반복 도전이 켜져 있지만 입장권이 없어 자동 재도전을 중단합니다.': '🔁 繰り返し挑戦がオンですが入場券がないため、自動再挑戦を中断します。',
        '🏛️ 미궁 {clearedFloor}층 돌파!{fossilSummary}': '🏛️ 迷宮{clearedFloor}層を突破!{fossilSummary}',
        '🌌 희귀 화석 [심연 화석]을 발견했습니다!': '🌌 レアな化石 [深淵の化石] を発見しました!',
        '🕳️ 지하계 {floor}층 돌파! {highestFloor}층까지 하강 가능합니다.': '🕳️ 地下界{floor}層を突破! {highestFloor}層まで下降できます。',
        '🛡️ {retreatZoneName} 물러나 레벨을 {ACT_RETREAT_LEVELS} 올린 뒤 다시 도전합니다.': '🛡️ {retreatZoneName}へ退いてレベルを{ACT_RETREAT_LEVELS}上げてから再挑戦します。',
        '🪓 나무꾼 전투 정산 대기 점수 +{score} (루프 정산 시 반영)': '🪓 木こり戦の清算待ち点数 +{score} (ループ清算時に反映)',
        '🛡️ 지하계 {value}층으로 물러나 다시 내려갑니다.': '🛡️ 地下界{value}層へ退いて再び下ります。',
        '🛡️ 절대 수호: 피해 무효!': '🛡️ 絶対守護: ダメージ無効!',
        '혹독한 한기: 생명력 재생 억제 {round}%': '酷寒: 生命力再生抑制 {round}%',
        '☠️ 하늘이 갈라지고 도끼날의 그림자가 전장을 뒤덮습니다.': '☠️ 空が裂け、斧の刃の影が戦場を覆います。',
        '혼돈 밖은 루프 10 이후 개방됩니다.': '混沌の外はループ10以降に開放されます。',
