        '📏 나무꾼의 잔상 도전 시작: 30초 동안 최대 피해를 기록하세요. (허수아비는 공격하지 않습니다)': '📏 木こりの残像への挑戦開始: 30秒間で最大ダメージを記録してください。(かかしは攻撃しません)',
        '🧭 새 루프 프리셋 자동 투자: {nodes}개 노드 활성화': '🧭 新ループのプリセット自動投資: {nodes}個のノードを有効化',
