        '루프 {value} 달성. 이번 여정의 기록과 다음 해금 요소를 확인하세요.': 'ループ{value}達成。今回の旅の記録と次の解放要素を確認してください。',
        '혼돈 루프와 우주계 루프 조건을 모두 달성했습니다. 진행할 루프 경로를 선택하세요.': '混沌ループと宇宙界ループの条件を両方達成しました。進めるループのルートを選んでください。',
