        '🌌 나무꾼의 경계가 갈라지며 혼돈계가 해금되었습니다.': '🌌 木こりの境界が裂け、混沌界が解放されました。',
        '🪓 나무꾼 피해율 기록: {woodsmanBestDamagePct}% / 해금 조건 10%': '🪓 木こりへのダメージ率記録: {woodsmanBestDamagePct}% / 解放条件 10%',
        '🪨 망자 감시 보호막 재생: {maxAmount}': '🪨 亡者監視のシールド再生: {maxAmount}',
