        '🌌 {name}의 우주계 보스 디버프: {label} -{value}%': '🌌 {name}の宇宙界ボスデバフ: {label} -{value}%',
        '[{classLabel}] 5차 특화 개방: 전직 포인트 +2, 키스톤 포인트 +1': '[{classLabel}] 第5特化を開放: 転職ポイント +2、キーストーンポイント +1',
        '🧪 확산 반응: 남은 상태이상이 주변 적 {length}마리에게 퍼졌습니다.': '🧪 拡散反応: 残った状態異常が周囲の敵{length}体に広がりました。',
        '⛔ 적이 {ENEMY_CROWD_PAUSE_LIMIT}기 이상 몰려 맵 진행이 멈췄습니다. 적 수를 줄이면 다시 전진합니다.': '⛔ 敵が{ENEMY_CROWD_PAUSE_LIMIT}体以上集まり、マップ進行が止まりました。敵の数を減らすと再び前進します。',
