        '🪓 나무꾼의 저주: 전투가 끝날 때까지 매초 받는 피해가 0.01%씩 증가합니다.': '🪓 木こりの呪い: 戦闘が終わるまで毎秒受けるダメージが0.01%ずつ増加します。',
        '🪓 나무꾼의 저주 중첩: 받는 피해 +{value}%': '🪓 木こりの呪いの重複: 受けるダメージ +{value}%',
        '🌌 아스트라의 표식이 바뀝니다: {name}': '🌌 アストラの標が変わります: {name}',
