        '👑 10개 갈림길을 완료해 여왕벌이 등장했습니다. 여왕벌을 처치하면 벌집 원정이 완료됩니다.': '👑 10の分かれ道を完了し、女王蜂が登場しました。女王蜂を倒すと蜂の巣遠征が完了します。',
