        '🌌 자동입장: 대균열이 열려 즉시 진입합니다.': '🌌 自動入場: 大亀裂が開いたため即座に進入します。',
        '🌌 대균열 진입! 일반 몬스터 0.5%, 정예 3%씩 게이지를 채워 균열 군주를 소환합니다. 전리품은 군주 처치 시 쏟아집니다.': '🌌 大亀裂に進入! 通常モンスター0.5%、精鋭3%ずつゲージを溜めて亀裂の君主を召喚します。戦利品は君主討伐時にあふれ出ます。',
        '먼저 지하계 10층 단위 보상으로 지하석 번호를 해금하세요.': '先に地下界の10層ごとの報酬で地下石の番号を解放してください。',
        '지하석 조각이 부족합니다. (필요: {need})': '地下石の欠片が足りません。(必要: {need})',
