        '창공의 탑은 영구 해금 후 해당 루프에서 혼돈에 입성하면 입장할 수 있습니다.': '蒼穹の塔は永久解放後、そのループで混沌に入ると入場できます。',
        '창공의 탑이 열린 뒤 창공석을 만들 수 있습니다.': '蒼穹の塔が開いた後に蒼穹石を作れます。',
