        '범위 피해 +20%, 적을 처치하고 남은 피해가 다른 적 모두에게 튐': '範囲ダメージ +20%、敵を倒して余ったダメージが他のすべての敵に跳ねる',
        '점화 피해 +35%, 점화가 점화 확률의 40% 확률로 30% 증폭되고, 증폭된 점화 위에 새 점화가 걸리면 남은 점화 피해의 15%가 바로 터짐': '発火ダメージ +35%、発火が発火確率の40%の確率で30%増幅され、増幅した発火の上に新しい発火が掛かると残った発火ダメージの15%がすぐ弾ける',
        '포션 스킬 피해 +60%, 화염 피해 +35%, 처치한 적이 15% 확률로 터져 다른 적에게 그 적 최대 생명력 20%의 피해': 'ポーションスキルダメージ +60%、火ダメージ +35%、倒した敵が15%の確率で弾け、他の敵にその敵の最大生命力20%のダメージ',
        '물리 피해 감소 +6%, 회피 +15%, 점화에 걸리지 않음': '物理ダメージ軽減 +6%、回避 +15%、発火にかからない',
        '포션 스킬 피해 +120%, 범위 피해 +50%, 타격 시 10% 확률로 준 피해의 60%를 다른 적 모두에게': 'ポーションスキルダメージ +120%、範囲ダメージ +50%、打撃時に10%の確率で与えたダメージの60%を他のすべての敵に',
        '물리 피해 10% 증폭, 방어도 15% 증가': '物理ダメージ 10%増幅、防御力 15%増加',
