        '생명력이 50% 이상으로 회복/흡수되지 않음, 치명타 확률 +3%p, 치명타 피해 배율 +15%, 연속 타격 +5%, 공격 속도 5% 증폭, 이동 속도 15% 증폭, 최종 피해 3% 증폭': '生命力が50%以上に回復/吸収されない、クリティカル率 +3%p、クリティカルダメージ倍率 +15%、連続打撃 +5%、攻撃速度 5%増幅、移動速度 15%増幅、最終ダメージ 3%増幅',
        '모든 주는 피해 10% 증폭, 받는 피해 10% 증폭': 'すべての与えるダメージ 10%増幅、受けるダメージ 10%増幅',
        '물리 피해 15% 증폭, 물리가 아닌 피해 20% 감폭': '物理ダメージ 15%増幅、物理以外のダメージ 20%減幅',
