        '치명타가 아닌 타격 시 다음 타격 치명타 확률 +5%p, 치명타 발동 시 초기화': 'クリティカルでない打撃時、次の打撃のクリティカル率 +5%p、クリティカル発動時にリセット',
        '적이 3기 이상 주변에 있으면 받는 피해 20% 감폭, 주는 피해 20% 증폭': '敵が3体以上周囲にいると受けるダメージ 20%減幅、与えるダメージ 20%増幅',
        '이동 후 첫 타격 피해 30% 증폭 및 첫 받는 피해 30% 감폭': '移動後の最初の打撃ダメージ 30%増幅、最初に受けるダメージ 30%減幅',
        '공격 후 적 생명력 20% 미만 즉시 처치(보스 10%)': '攻撃後、敵の生命力20%未満なら即時討伐(ボスは10%)',
        '회피 150당 연속 타격 +1%p(최대 +15%p), 방어도 500당 치명타 확률 +1%p(최대 +10%p)': '回避150につき連続打撃 +1%p (最大 +15%p)、防御力500につきクリティカル率 +1%p (最大 +10%p)',
