        '모든 원소 저항 +15%, 원소 저항 최대치 +3%, 카오스 저항 -10%': 'すべての元素耐性 +15%、元素耐性の最大値 +3%、カオス耐性 -10%',
        '에너지 보호막 재생이 끊기지 않음, 최대 생명력 -15%': 'エネルギーシールド再生が途切れない、最大生命力 -15%',
        '모든 스킬이 화염/냉기/번개 33% 영향 스킬로 변화': 'すべてのスキルが火/冷気/雷33%影響スキルに変化',
        '카오스 저항이 가장 높은 원소 저항의 50%만큼 상승, 카오스 저항만큼 원소 최종 피해 증가': 'カオス耐性が最も高い元素耐性の50%分上昇、カオス耐性分元素最終ダメージ増加',
