        '빠른 연속 공격과 높은 치명타 확률로 압박합니다.': '速い連続攻撃と高いクリティカル率で圧迫します。',
        '생명력 위에 큰 에너지 보호막을 추가로 두릅니다.': '生命力の上に大きなエネルギーシールドを追加で纏います。',
        '높은 회피로 명중이 낮은 공격을 흘려냅니다.': '高い回避で命中の低い攻撃を受け流します。',
        '방어도와 피해 감소로 물리 타격을 억제합니다.': '防御力とダメージ軽減で物理打撃を抑えます。',
        '무거운 물리 충돌과 운석 장갑이 중심인 은하입니다.': '重い物理衝突と隕石の装甲が中心の銀河です。',
        '모든 적이 생명력 위에 성간 보호막을 두르는 은하입니다.': 'すべての敵が生命力の上に星間シールドを纏う銀河です。',
        '주 피해와 카오스 피해가 겹치는 이중성 은하입니다.': '主ダメージとカオスダメージが重なる連星の銀河です。',
        '높은 치명타와 저항 관통으로 방어의 빈틈을 심판합니다.': '高いクリティカルと耐性貫通で防御の隙を裁きます。',
        '빠른 공격과 높은 회피로 완성 빌드를 추격하는 은하입니다.': '速い攻撃と高い回避で完成したビルドを追う銀河です。',
        '위협을 낮춰 처음 연결하는 항로입니다.': '脅威を下げて初めてつなぐ航路です。',
        '성간 잔해를 회수해 탐사 보상을 높입니다.': '星間の残骸を回収して探査報酬を高めます。',
        '강한 개체를 추적해 밀도 높은 보상을 노립니다.': '強い個体を追跡して密度の高い報酬を狙います。',
        '불안정한 균열을 가로질러 큰 수익을 노립니다.': '不安定な亀裂を横切って大きな利益を狙います。',
        '빨라지는 성운 폭풍 속에서 공명 잔광을 수확합니다.': '速まる星雲の嵐の中で共鳴の残光を収穫します。',
        '드물게 관측되는 흑성 신호입니다. 위험과 보상이 크게 증폭됩니다.': 'まれに観測される黒星の信号です。危険と報酬が大きく増幅されます。',
        '봉인된 보물함': '封印された宝箱',
        '이제 탐험 중 봉인된 보물함을 발견할 수 있습니다.': '探索中に封印された宝箱を見つけられるようになりました。',
        '매복': '待ち伏せ',
        '이제 탐험 중 매복을 만날 수 있습니다.': '探索中に待ち伏せに遭うようになりました。',
        '알집': '卵の房',
        '이제 탐험 중 알집을 발견할 수 있습니다.': '探索中に卵の房を見つけられるようになりました。',
        '보급 상자': '補給箱',
        '은빛 상자': '銀の箱',
        '황금 보급 상자': '黄金の補給箱',
        '받는 피해': '受けるダメージ',
        '구간 넓이': '区間の広さ',
