        '“제6호 시제품: 갑주의 안쪽을 파고드는 역날 구조이나, 쥐는 이의 손목까지 함께 벤다. 폐기한다.”': '「第6号試作品: 甲冑の内側に食い込む逆刃構造だが、握る者の手首まで共に斬る。廃棄する。」',
