        '일곱 번째 날, 완성작(제7호 봉인록)': '七番目の刃、完成作(第7号封印録)',
        '나무꾼이 끝내 손에서 놓지 않은 일곱 번째 날, 완성작을 꺾은 기록입니다.': '木こりが最後まで手放さなかった七番目の刃、完成作を折った記録です。',
        '“제7호 최종본: 앞선 다섯 시제품의 결함을 모두 도려낸 무결점의 날붙이. 끝내 손에서 놓지 않고 보관한다.”': '「第7号最終版: 先の五つの試作品の欠陥をすべてえぐり取った無欠の刃物。最後まで手放さず保管する。」',
        '“…허나 어째서 우물 바닥에 버려졌던 첫 번째 파편이, 모루 위의 완성작보다 더 날카롭게 울리는가.”': '「…だがなぜ、井戸の底に捨てられた最初の破片が、金床の上の完成作より鋭く鳴るのか。」',
        '(벼림꾼 오르가의 모루터 폐기 장부 제7항)': '(鍛冶師オルガの金床廃棄帳簿 第7項)',
        '잔향체, 아스트라': '残響体、アストラ',
        '영구 스킬트리 포인트 +2': '永久スキルツリーポイント +2',
        '다섯 별의 잔향이 뭉친 아스트라를 쓰러뜨린 기록입니다.': '五つの星の残響が集まったアストラを倒した記録です。',
        '“다섯 은하의 군주가 소멸한 궤도 위에, 별들의 유언이 뭉쳐 하나의 잔향체가 깨어났다.”': '「五つの銀河の君主が消滅した軌道の上に、星々の遺言が集まって一つの残響体が目覚めた。」',
        '“하말리스의 장갑, 디프다르의 심연, 주베누비아의 균형, 주벤샤말의 심판, 에니프론의 붕괴.”': '「ハマリスの装甲、ディフダルの深淵、ズベヌビアの均衡、ズベンシャマルの審判、エニフロンの崩壊。」',
        '“다섯 별의 무게를 모두 베어낸 칼날만이 성간(星間)의 침묵을 통과한다.”': '「五つの星の重みをすべて斬った刃だけが、星間の沈黙を通り抜ける。」',
        '지핵군주, 모르그란': '地核君主、モルグラン',
        '지하계 끝에서 지핵군주 모르그란을 쓰러뜨린 기록입니다.': '地下界の果てで地核君主モルグランを倒した記録です。',
        '“지하계의 끝은 암반이 아니라 세계수의 뿌리를 아래에서 태우던 거대한 지핵(地核)의 심장이었다.”': '「地下界の果ては岩盤ではなく、世界樹の根を下から焼いていた巨大な地核の心臓だった。」',
        '“모르그란의 용광로가 식자, 뿌리 아래를 짓누르던 영겁의 침묵에 첫 균열이 갔다.”': '「モルグランの溶鉱炉が冷めると、根の下を押さえつけていた永劫の沈黙に最初の亀裂が入った。」',
        '무광해의 포식자, 탈라사': '無光海の捕食者、タラッサ',
        '무광해의 해구에서 포식자 탈라사를 쓰러뜨린 기록입니다.': '無光海の海溝で捕食者タラッサを倒した記録です。',
        '“빛이 닿지 않는 천 미터 해구(海溝)에서, 뿌리가 흘린 썩은 수액을 먹고 자란 고대 포식자의 기록.”': '「光の届かぬ千メートルの海溝で、根が流した腐った樹液を食べて育った古代の捕食者の記録。」',
        '“검은 조류를 가르고 돌아온 칼날에는 심해의 수압조차 꺾지 못한 서슬이 남았다.”': '「黒い潮流を裂いて戻った刃には、深海の水圧さえ折れなかった切っ先が残った。」',
        '빈 왕좌의 집행자, 카엘룸': '空の王座の執行者、カエルム',
        // ── 2026-11-04 표에서 넣음(w2b06-ja.json) ──
