        '“창공의 탑 꼭대기에 놓인 왕좌는 태초부터 주인이 없었다.”': '「蒼穹の塔の頂に置かれた王座は、太初より主を持たなかった。」',
        '“텅 빈 왕좌의 질서를 수호하던 자동 집행자가 멈춰 서자, 수관 너머의 천공이 비로소 열렸다.”': '「空の王座の秩序を守っていた自動執行者が止まると、樹冠の彼方の天空がようやく開いた。」',
        '경계의 관측자, 베일라': '境界の観測者、ベイラ',
        '마지막 경계에서 관측자 베일라를 넘어선 기록입니다.': '最後の境界で観測者ベイラを越えた記録です。',
