        '그루터기 함에서 비활성화된 그루터기 아이템 하나마다 생명력 +5%, 방어도 +25(최대 4개).': '切り株の箱で無効化された切り株アイテム一つごとに生命力 +5%、防御力 +25（最大4個）。',
        '맞닿은 그루터기 아이템 하나마다 물리 피해 +7%, 생명력 −2%.': '隣接する切り株アイテム一つごとに物理ダメージ +7%、生命力 −2%。',
        '같은 가로줄이나 세로줄에 있는 깨어난 부적의 일반 줄을 18% 더 얻습니다.': '同じ横列か縦列にある目覚めた護符の通常行を 18% 多く得ます。',
        '다른 깨어난 부적의 소환수 줄을 15% 더 얻고, 그런 부적이 4개 이상이면 소환수 한도 +1.': '他の目覚めた護符の召喚獣行を 15% 多く得、そうした護符が4個以上なら召喚上限 +1。',
