        '{checkpointM}m부터': '{checkpointM}m から',
        '심해로 돌아가기': '深海に戻る',
        '수면으로 복귀': '水面に復帰',
        ' data-exploration-departure data-departure-title="수면으로 올라갈까요?" data-departure-message="{checkpointM}m 체크포인트 뒤의 진행은 사라집니다. 이미 얻은 물고기와 재화는 유지됩니다."': 'data-exploration-departure data-departure-title="水面へ上がりますか？" data-departure-message="{checkpointM}m チェックポイント以降の進行は消えます。すでに得た魚と財貨は維持されます。"',
