        '수압': '水圧',
        '{depthM}단계': '{depthM}段階',
        '강화': '強化',
        '지금': '今',
        '몬스터를 쓰러뜨린 만큼 내려갑니다. 정예는 {eliteKillMul}배입니다.': 'モンスターを倒した分だけ下ります。精鋭は{eliteKillMul}倍です。',
        '{value}m마다 길을 막고, 닿으면 남은 무리를 두고 바로 가디언 방으로 갑니다. 쓰러뜨려야 더 내려가고, 가디언에게 쓰러지면 잠수가 끝납니다.': '{value}mごとに道を塞ぎ、到達すると残りの群れを置いてすぐガーディアンの部屋へ行きます。倒さなければ下れず、ガーディアンに倒されると潜水が終わります。',
        '초당 {st} 줄어들고, 철갑 패각충과 정예, 가디언이 부른 졸개를 쓰러뜨리면 공기 방울로 찹니다. 다 떨어지면 익사 피해를 받다가 수면으로 올라와 잠수를 시작한 사냥터로 돌아오고, 체크포인트 뒤 진행은 사라집니다.': '毎秒 {st} 減り、鉄甲貝殻虫と精鋭、ガーディアンが呼んだ手下を倒すと空気の泡で満たされます。尽きると溺死ダメージを受けて水面に上がり、潜水を始めた狩り場に戻り、チェックポイント以降の進行は消えます。',
        '켜 두면 산소가 떨어지거나 가디언에게 쓰러져 떠오른 뒤, 사냥터 하나를 깨고 다시 잠수합니다. 가디언 앞에 막혔으면 지난 가디언 자리부터 내려가 물고기를 모읍니다. 무리에게 쓰러지거나, 리프트도 가디언 처치도 물고기도 없이 {missLimit}번 떠오르면 멈춥니다. 새 루프의 첫 잠수와 자리를 비운 동안의 정산에서는 다시 잠수하지 않습니다.': 'オンにすると、酸素切れやガーディアンに倒されて浮上した後、狩り場を一つ突破して再び潜水します。ガーディアンの前で塞がれていれば前のガーディアンの位置から下って魚を集めます。群れに倒されるか、リフトもガーディアン撃破も魚もなしに{missLimit}回浮上すると止まります。新しいループの最初の潜水と不在中の精算では再潜水しません。',
