        "레벨이 올라 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.\n오른 능력치는 ‘캐릭터’에서 확인할 수 있습니다.": "レベルが上がりスキルツリーポイントを得ました。\n「スキルツリー」で開始地点と繋がったノードを選んで取ってください。\n上がった能力値は「キャラクター」で確認できます。",
        '첫 장비': '最初の装備',
        "장비를 얻었습니다. 자동 장착이 켜져 있으면 빈 칸에 맞는 장비를 바로 착용합니다.\n‘장비’에서 착용한 장비의 효과를 확인하고, 보관 중인 장비와 비교하세요.\n바꿔 입으면 전투 화면의 생명 구슬 위에 DPS 변화가 뜹니다.": "装備を得ました。自動装着がオンなら空きスロットに合う装備をすぐ着用します。\n「装備」で着用した装備の効果を確認し、保管中の装備と比べてください。\n着替えると戦闘画面のライフオーブの上にDPSの変化が表示されます。",
        '무기와 스킬룬': '武器とスキルルーン',
        "스킬룬마다 쓸 수 있는 무기가 있습니다. 지금 무기로 쓸 수 없는 룬은 흐리게 보이고, 카드에 필요한 무기가 적혀 있습니다.\n장착한 룬을 쓸 수 없는 무기로 바꾸면 기본 공격으로 싸우다가, 맞는 무기를 들면 그 룬으로 돌아갑니다.": "スキルルーンごとに使える武器があります。今の武器で使えないルーンは薄く表示され、カードに必要な武器が書かれています。\n装着したルーンを使えない武器に変えると基本攻撃で戦い、合う武器を持つとそのルーンに戻ります。",
