        '부적과 고급 수확 제작': '護符と上級収穫製作',
        '“미궁에서 건진 봉인편린에는 잘려 나간 옛 가지들의 원한이 서려 있어. 네 피를 먹여 깨우면 어떤 갑옷보다 든든한 부적이 되지. 그루터기 함의 식물로 하는 고급 수확 제작은 내가 가르쳐줄 수 있지. 조심해 독성이 강할 거야. 그만큼의 값도 받아야겠고.”': '「迷宮で拾った封印の欠片には、切り落とされた古い枝たちの怨みが宿っている。お前の血を与えて目覚めさせれば、どんな鎧より頼もしい護符になる。切り株の箱の植物を使う上級収穫製作なら私が教えてやれる。気をつけろ、毒性が強いはずだ。それなりの値も取るぞ」',
        '다음: {act} 「{title}」': '次: {act}「{title}」',
