        '죽은 잔뿌리들이 겹겹이 엉켜 중정으로 오르는 길을 가로막은 지하 성소.': '枯れた細根が幾重にも絡み合い、中庭へ上る道を塞いだ地下の聖所。',
        '아래쪽 뿌리의 수액을 빨아들여 영원을 유지하는 정원.': '下の根の樹液を吸い上げて永遠を保つ庭園。',
        '수액을 모두 빼앗긴 채 허공에 매달려 말라붙은 뿌리 숲.': '樹液をすべて奪われ、虚空に吊られたまま干からびた根の森。',
        '하층의 수액을 중정으로 실어 나르는 황금 길의 교차로.': '下層の樹液を中庭へ運ぶ黄金の道の交差点。',
        '우물에서 건진 파편을 칼날로 담금질한 비밀 공방.': '井戸から引き上げた欠片を刃へと焼き入れした秘密の工房。',
        '수액 공급이 끊겨 시들어 버린 정원사의 마지막 보루.': '樹液の供給が途絶えて枯れてしまった庭師の最後の砦。',
        '수관에 모든 수액을 빼앗기고 속이 텅 비어버린 고목 도시.': '樹冠にすべての樹液を奪われ、中ががらんどうになった古木の都市。',
        '기억에 없는 당신의 발자국이 바닥마다 포개어져 남은 회랑.': '覚えのないあなたの足跡が床ごとに重なって残る回廊。',
        '잘려 나간 가지들의 유해를 접붙여 마지막 고치를 품은 수관.': '切り落とされた枝たちの亡骸を接ぎ木し、最後の繭を抱いた樹冠。',
        '아홉 삽목의 울음이 하나의 왕관으로 맞물린 세계수의 끝.': '九つの挿し木の慟哭が一つの王冠に噛み合った世界樹の果て。',
        '분석 중 오류가 발생했습니다. 다시 시도하세요.': '分析中にエラーが発生しました。もう一度お試しください。',
