        '액트 3을 클리어하면 무료로 해금됩니다. 기본 공격 대상과 전투 거리를 정하고, 조건에 따라 행동하는 규칙을 만들 수 있습니다.': 'アクト3をクリアすると無料で解放されます。基本の攻撃対象と戦闘距離を決め、条件に応じて行動するルールを作れます。',
