        '군주의 핵/창공의 정수 재료와 해당 강화 레벨': '君主の核・蒼穹の精髄の素材と、それらによる強化レベル',
        '강화마다 피해 4% 증폭. 5강이면 룬 레벨 +1. 재료와 강화는 루프마다 초기화됩니다.': '強化ごとにダメージが4%増幅。+5でルーンレベル+1。素材と強化はループごとにリセットされます。',
