        '창공의 탑에서 얻는 별도 재화입니다. 창공을 해금한 뒤 영구 강화에 사용할 수 있습니다. 보유량과 영구 룬 강화는 유지됩니다.': '蒼穹の塔で手に入る専用通貨です。蒼穹の解放後に永久強化に使えます。所持数とルーンの永久強化は維持されます。',
        '각성 룬': '覚醒ルーン',
