        '그루터기 함, 열린 칸, 접붙이기, 봉인 칸의 아이템과 성장': '切り株の箱、開放済みのマス、接ぎ木、封印欄のアイテムと成長',
        '봉인 칸 밖의 그루터기 아이템과 부적(판, 보관함, 생육함)': '封印欄の外にある切り株アイテムと護符（盤面・保管庫・育成箱）',
        '루프와 전투 기록을 비교합니다.': 'ループと戦闘の記録を比較できます。',
