        '화석 복원': '化石の復元',
        '화석 옵션 장비': '化石オプション付き装備',
        '고대 미궁에서 원시 화석과 고대 원시 화석이 떨어집니다. 제작실에서 원시 화석을 복원하고 남는 화석을 정제할 수 있습니다. 화석 전용 옵션 장비도 떨어집니다.': '古代迷宮で原始の化石と古代の原始化石が落ちるようになります。工房で原始の化石を復元し、余った化石を精製できます。化石専用オプション付きの装備も落ちるようになります。',
        '고급 수확 제작': '上級収穫製作',
