        '공허 칸의 할당과 옵션': '虚空枠の割り当てとオプション',
        '화석, 봉인편린': '化石と封印の欠片',
        '고대 미궁이 해금됩니다. 미궁을 등반해 전용 보상을 얻을 수 있습니다.': '古代迷宮が解放されます。迷宮を登り、専用の報酬を獲得できます。',
        '주얼': 'ジュエル',
        '장비 소켓': '装備ソケット',
        '장비 소켓에 끼우는 주얼이 떨어집니다. 반지, 목걸이, 허리띠에는 소켓이 있고 다른 장비는 공허의 끌로 뚫을 수 있습니다.': '装備ソケットにはめるジュエルが落ちるようになります。指輪、首飾り、ベルトにはソケットがあり、ほかの装備には虚空のノミで開けられます。',
        '주얼 보관함, 장비 소켓의 주얼(루프 봉인 장비는 유지), 주얼 재료': 'ジュエル保管庫、装備ソケットのジュエル（ループ封印した装備のものは維持）、ジュエル素材',
        '그루터기 함 옵션': '切り株の箱のオプション',
        '고대 미궁의 봉인편린으로 부적을 풀고, 그루터기 함에 배치해 처치로 깨울 수 있습니다.': '古代迷宮で得た封印の欠片で護符の封印を解き、切り株の箱に置いて敵を倒すと目覚めさせられます。',
        '그루터기 함의 부적과 배치(루프마다 다시 잠듦)': '切り株の箱の護符と配置（ループごとに再び眠る）',
        '꿀, 밀랍': '蜂蜜と蜜蝋',
