        '벌집 개방/클리어 기록': '蜂の巣の開放・クリア記録',
        '꿀/꽃가루/밀랍/벌침/벌집 열쇠 등 보상 재료': '蜂蜜・花粉・蜜蝋・蜂の針・蜂の巣の鍵などの報酬素材',
        '공허 균열이 해금됩니다. 도전해서 전용 재료를 모을 수 있습니다.': '虚空の亀裂が解放されます。挑戦して専用素材を集められます。',
        '균열 클리어 횟수/대균열 개방 및 클리어 기록': '亀裂のクリア回数、大亀裂の開放・クリア記録',
        '공허 끌 등 보상 재료': '虚空のノミなどの報酬素材',
        '장비 융합': '装備融合',
        '시간의 균열이 해금됩니다. 시간압을 조절하고 장비 융합에 도전할 수 있습니다.': '時の亀裂が解放されます。時間圧を調整し、装備融合に挑戦できます。',
        '시간압, 융합 횟수, 최근 융합 기록': '時間圧、融合回数、最近の融合記録',
        '제단과 제단 장비, 일반 인벤토리 장비. 루프 봉인 장비는 유지됩니다.': '祭壇と祭壇の装備、通常のインベントリ内の装備。ループ封印した装備は維持されます。',
        '웨이브 방어': 'ウェーブ防衛',
        '군락지가 해금됩니다. 몰려오는 웨이브를 막아 낼 수 있습니다.': '群生地が解放されます。押し寄せるウェーブを防ぎます。',
        '군락지 웨이브/군락 수호판/수호 아이템과 관련 재료': '群生地のウェーブ・群落守護板・守護アイテムと関連素材',
        '입장 조건을 달성하면 창공의 탑을 등반할 수 있습니다.': '入場条件を満たすと蒼穹の塔に登れます。',
        '응축된 창공의 정수/영구 룬 강화/창공석 성장': '凝縮された蒼穹の精髄・ルーンの永久強化・蒼穹石の成長',
        '루프별 등반 횟수 제한': 'ループごとの挑戦回数制限',
        '코어 슬롯': 'コアスロット',
        '지하계 10층을 넘기면 지하계 적에게서 코어가 떨어집니다. 장비창 왼쪽 위에 코어 슬롯이 생깁니다.': '地下界の10層を越えると、地下界の敵がコアを落とすようになります。装備ウィンドウの左上にコアスロットが現れます。',
