        '재능 개화 조건을 달성하면 재능을 관리할 수 있습니다.': '才能開花の条件を満たすと才能を管理できます。',
        '개화 카드/카드 레벨/개화 조합 기록': '開花カード・カードレベル・開花の組み合わせ記録',
        '이번 루프의 개화 직업/5차 특화 포인트와 투자': '今回のループの開花クラス・第5次特化ポイントと割り当て',
        '시련에서 얻는 개화 카드와 레벨은 영구 성장입니다. 해당 루프의 5차 특화는 다음 루프에 다시 개화해야 합니다.': '試練で得る開花カードとレベルは永久成長です。そのループの第5次特化は、次のループで再び開花させる必要があります。',
